/* CACHE and ASSETS are generated by mix offline.build. */
self.addEventListener("install", event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // Installation fails atomically if any runtime asset is missing.
    await cache.addAll(ASSETS.map(url => new Request(url, {cache: "reload"})));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", event => {
  event.waitUntil((async () => {
    // Retain older asset caches for tabs still running an older WASM bundle.
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", event => {
  const {request} = event;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin) return;
  if (request.mode === "navigate" && ["/", "/offline"].includes(url.pathname)) {
    event.respondWith((async () => {
      try {
        const response = await fetch(request);
        if (response.ok) return response;
      } catch (_) { /* Serve the complete local application below. */ }
      return (await caches.open(CACHE)).match("/offline");
    })());
  } else if (ASSETS.includes(url.pathname) && url.pathname !== "/offline") {
    event.respondWith((async () => (await (await caches.open(CACHE)).match(url.pathname)) || fetch(request))());
  }
});
